<script setup>import {router,useForm} from '@inertiajs/vue3'; import AppLayout from '../../Layouts/AppLayout.vue'; const props=defineProps({routes:Array,openRoutes:Array,completedRoutes:Array,selectedRoute:Object,date:String,googleMapsKey:String,endpoints:Object}); const status=useForm({status:props.selectedRoute?.status||'planned'}); const visit=stop=>router.patch(props.endpoints.visitTemplate.replace('__STOP__',stop.id),{notes:''},{preserveScroll:true}); const saveStatus=()=>status.patch(`/rutas/${props.selectedRoute.id}/estado`,{preserveScroll:true}); const done=r=>r.stops.filter(s=>s.status==='visited').length;</script>
<template><AppLayout title="Rutas de cobranza" eyebrow="Operación en campo" description="Organiza la jornada y registra cada visita."><template #header-actions><div class="flex gap-2"><input type="date" :value="String(date).slice(0,10)" class="control m-0" @change="router.get(endpoints.index,{date:$event.target.value})"><a :href="endpoints.create" class="btn-primary">Nueva ruta</a></div></template><section class="grid gap-3 sm:grid-cols-3"><div class="live-metric" data-tone="blue"><p>Rutas del día</p><strong>{{routes.length}}</strong></div><div class="live-metric" data-tone="emerald"><p>Visitas realizadas</p><strong>{{routes.reduce((n,r)=>n+done(r),0)}}</strong></div><div class="live-metric" data-tone="gold"><p>Pendientes</p><strong>{{routes.reduce((n,r)=>n+r.stops.filter(s=>s.status==='pending').length,0)}}</strong></div></section><div class="mt-4 grid gap-4 xl:grid-cols-[320px_1fr]"><aside class="card overflow-hidden"><div class="section-heading"><h2 class="font-semibold">Rutas</h2></div><div class="divide-y"><a v-for="route in routes" :key="route.id" :href="`${endpoints.index}?date=${String(date).slice(0,10)}&route=${route.id}`" class="block p-4" :class="selectedRoute?.id===route.id?'bg-blue-50':'hover:bg-slate-50'"><div class="flex justify-between"><p class="font-semibold">{{route.name}}</p><span class="badge bg-slate-100 text-slate-600">{{route.status}}</span></div><p class="mt-1 text-[10px] text-slate-400">{{route.collector.user.name}} · {{done(route)}}/{{route.stops.length}}</p></a></div></aside><div v-if="selectedRoute" class="space-y-4"><section class="analytics-panel p-5 text-white"><div class="flex flex-wrap justify-between gap-3"><div><p class="dark-kicker">Ruta seleccionada</p><h2 class="mt-2 text-lg font-semibold">{{selectedRoute.name}}</h2><p class="text-xs text-slate-300">{{selectedRoute.code}} · {{selectedRoute.collector.user.name}}</p></div><form class="flex gap-2" @submit.prevent="saveStatus"><select v-model="status.status" class="rounded-lg bg-white px-3 text-xs text-slate-800"><option value="planned">Programada</option><option value="active">En recorrido</option><option value="completed">Finalizada</option><option value="cancelled">Cancelada</option></select><button class="btn-primary">Cambiar estado</button></form></div></section><section class="card overflow-hidden"><div class="section-heading flex justify-between"><h2 class="font-semibold">Clientes</h2><a :href="`/rutas/${selectedRoute.id}/editar`" class="text-xs font-semibold text-blue-700">Editar ruta</a></div><div class="divide-y"><div v-for="stop in selectedRoute.stops" :key="stop.id" class="flex items-center gap-3 p-4"><span class="grid h-8 w-8 place-items-center rounded-lg bg-blue-50 text-xs font-bold text-blue-700">{{stop.position}}</span><div class="min-w-0 flex-1"><p class="font-semibold">{{stop.client.full_name}}</p><p class="truncate text-[10px] text-slate-400">{{stop.client.address}}</p></div><span class="badge" :class="stop.status==='visited'?'bg-emerald-50 text-emerald-700':'bg-amber-50 text-amber-700'">{{stop.status}}</span><button v-if="stop.status==='pending'" class="btn-soft" @click="visit(stop)">Marcar visita</button></div></div></section></div><section v-else class="card grid min-h-80 place-items-center text-slate-400">No hay rutas para la fecha.</section></div></AppLayout></template>
